sys_sg_write_back_action_item.execution_script:
(function WriteBackAction(parm_input, parm_variable, actionResult) {

    try {

        // -----------------------------------------------------
        // GET CURRENT CORRECTION REQUEST SYS_ID
        // Support both Mobile parameter locations
        // -----------------------------------------------------
        var requestSysId = '';

        if (
            parm_variable &&
            parm_variable['request_sys_id']
        ) {
            requestSysId =
                parm_variable['request_sys_id'];
        }

        else if (
            parm_input &&
            parm_input['request_sys_id']
        ) {
            requestSysId =
                parm_input['request_sys_id'];
        }


        gs.info(
            '[SmartAttend Approve] request_sys_id=' +
            requestSysId
        );


        var managerId =
            gs.getUserID();


        gs.info(
            '[SmartAttend Approve] logged_user=' +
            managerId
        );


        if (!requestSysId) {

            gs.error(
                '[SmartAttend Approve] ERROR: request_sys_id is empty'
            );

            return;
        }


        // -----------------------------------------------------
        // GET CORRECTION REQUEST
        // -----------------------------------------------------
        var correction =
            new GlideRecord(
                'x_1760545_smarta_0_attendance_correction_request'
            );


        if (!correction.get(requestSysId)) {

            gs.error(
                '[SmartAttend Approve] ERROR: correction request not found'
            );

            return;
        }


        gs.info(
            '[SmartAttend Approve] correction=' +
            correction.getValue('number')
        );


        gs.info(
            '[SmartAttend Approve] correction_manager=' +
            correction.getValue('manager')
        );


        // -----------------------------------------------------
        // SECURITY CHECK
        // -----------------------------------------------------
        if (
            correction.getValue('manager') !==
            managerId
        ) {

            gs.error(
                '[SmartAttend Approve] ERROR: logged user is not request manager'
            );

            return;
        }


        // -----------------------------------------------------
        // FIND PENDING APPROVAL
        // -----------------------------------------------------
        var approval =
            new GlideRecord(
                'sysapproval_approver'
            );


        approval.addQuery(
            'approver',
            managerId
        );


        approval.addQuery(
            'state',
            'requested'
        );


        // A custom-table approval commonly uses document_id.
        // Also allow sysapproval as a fallback.
        var approvalRef =
            approval.addQuery(
                'document_id',
                requestSysId
            );

        approvalRef.addOrCondition(
            'sysapproval',
            requestSysId
        );


        approval.query();


        gs.info(
            '[SmartAttend Approve] approvals_found=' +
            approval.getRowCount()
        );


        if (!approval.next()) {

            gs.error(
                '[SmartAttend Approve] ERROR: no pending approval found'
            );

            return;
        }


        gs.info(
            '[SmartAttend Approve] approval_sys_id=' +
            approval.getUniqueValue()
        );


        // -----------------------------------------------------
        // APPROVE
        // -----------------------------------------------------
        approval.setValue(
            'state',
            'approved'
        );


        approval.setValue(
            'comments',
            'Approved from SmartAttend Now Mobile.'
        );


        var updateResult =
            approval.update();


        gs.info(
            '[SmartAttend Approve] update_result=' +
            updateResult
        );


        if (!updateResult) {

            gs.error(
                '[SmartAttend Approve] ERROR: approval update failed'
            );

            return;
        }


        gs.info(
            '[SmartAttend Approve] SUCCESS: approval completed'
        );


    }

    catch (e) {

        gs.error(
            '[SmartAttend Approve] EXCEPTION: ' +
            e.message
        );

    }

})(
    parm_input,
    parm_variable,
    actionResult
);
